## 3. Result-Generation Logic (form data → recommendation)

Source: `client/src/lib/varicoceleLogic.ts`

```typescript
/**
 * Varicocele Embolization Clinical Decision Logic
 *
 * Guidelines:
 * - AUA/ASRM: Male Infertility Best Practice Policy (2022 update)
 *   https://www.auanet.org/guidelines-and-quality/guidelines/male-infertility
 * - EAU Guidelines on Male Infertility (2024)
 *   https://uroweb.org/guidelines/male-infertility
 * - CIRSE Standards of Practice on Varicocele Embolisation (2023)
 *   https://link.springer.com/article/10.1007/s00270-022-03293-x
 * - SIR Quality Improvement Guidelines for Percutaneous Transcatheter Embolization (2021)
 *   JVIR 2021;32(4):476-488. PMID 33610449
 * - Kim DK et al. Recent Guidelines and Perspectives for Varicocele. World J Mens Health 2025;43(4):748-757. PMID 40034026
 * - Chen H et al. Sclero-embolization vs surgical ligation meta-analysis. World J Urol 2025. PMID 41137990
 */

// ─── Input Types ────────────────────────────────────────────────────────────

export type VaricoceleGrade =
  | "subclinical"   // Ultrasound-only, not palpable
  | "grade1"        // Palpable only with Valsalva
  | "grade2"        // Palpable without Valsalva, not visible
  | "grade3";       // Visible without Valsalva ("bag of worms")

export type SemenQuality =
  | "normal"
  | "mildly_abnormal"    // 1 parameter below WHO 6th ed. reference
  | "moderately_abnormal" // 2+ parameters below reference
  | "severely_abnormal"  // Severe oligospermia / asthenospermia / teratospermia
  | "azoospermia";

export type PainStatus =
  | "none"
  | "mild_intermittent"
  | "persistent_moderate"
  | "severe_limiting";

export type PriorTreatment =
  | "none"
  | "prior_surgery_recurrent"   // Recurrence after surgical repair
  | "prior_embolization_recurrent";

export type Laterality = "left" | "right" | "bilateral";

export interface VaricoceleInput {
  // Demographics & presentation
  age: number;                          // Patient age in years
  isAdolescent: boolean;               // Age < 18
  laterality: Laterality;

  // Clinical grading (Dubin-Amelar)
  grade: VaricoceleGrade;

  // Fertility context
  infertilityDuration: number;         // Months of attempting conception (0 if not trying)
  partnerAge: number;                  // Female partner age (0 if not applicable)
  partnerFertilityStatus: "normal" | "reduced" | "unknown" | "not_applicable";
  semenQuality: SemenQuality;
  sdfElevated: boolean;                // Sperm DNA fragmentation elevated
  priorArtFailure: boolean;            // Prior IVF/ICSI failure
  nonObstructiveAzoospermia: boolean;  // NOA diagnosis

  // Symptoms
  pain: PainStatus;
  testicularAtrophy: boolean;          // >20% volume discrepancy (adolescents) or atrophy
  atrophyPercent: number;              // % volume discrepancy (0–100)

  // Anatomy & imaging
  veinDiameter: number;                // Max vein diameter in mm on Doppler US
  refluxOnValsalva: boolean;
  isolatedRightSided: boolean;         // Isolated right-sided varicocele

  // Treatment history
  priorTreatment: PriorTreatment;

  // Patient preferences & anatomy
  preferMinimallyInvasive: boolean;
  generalAnesthesiaRisk: boolean;      // High surgical risk
  anatomicAccessConcern: boolean;      // Concern for catheter access (e.g., prior pelvic surgery)
}

// ─── Output Types ────────────────────────────────────────────────────────────

export type TreatmentRecommendation =
  | "observe_monitor"
  | "embolization_preferred"
  | "surgery_preferred"
  | "embolization_or_surgery"
  | "embolization_for_recurrence"
  | "art_without_repair"
  | "multidisciplinary_noa"
  | "no_treatment_subclinical";

export type EvidenceLevel = "A" | "B" | "C" | "Expert";

export interface VaricoceleRecommendation {
  // Primary recommendation
  primaryRecommendation: TreatmentRecommendation;
  recommendationLabel: string;
  rationale: string;

  // Embolization candidacy
  embolizationCandidate: boolean;
  embolizationNotes: string[];

  // Surgery candidacy
  surgeryCandidate: boolean;
  surgeryNotes: string[];

  // Treatment indication
  treatmentIndicated: boolean;
  indicationReason: string;

  // Warnings and flags
  warnings: string[];
  urgentFlags: string[];

  // Clinical context
  fertilityContext: string;
  nextSteps: string[];

  // Evidence
  evidenceLevel: EvidenceLevel;
  guidelineSource: string;

  // Embolization-specific technical notes
  embolizationTechNotes: string[];
}

// ─── Core Logic ─────────────────────────────────────────────────────────────

export function assessVaricocele(input: VaricoceleInput): VaricoceleRecommendation {
  const warnings: string[] = [];
  const urgentFlags: string[] = [];
  const embolizationNotes: string[] = [];
  const surgeryNotes: string[] = [];
  const nextSteps: string[] = [];
  const embolizationTechNotes: string[] = [];

  // ── Step 1: Isolated right-sided varicocele flag ──
  if (input.isolatedRightSided) {
    urgentFlags.push(
      "Isolated right-sided varicocele: consider abdominal imaging to exclude retroperitoneal pathology (malignancy, IVC obstruction) before proceeding with embolization."
    );
  }

  // ── Step 2: Subclinical varicocele — no treatment ──
  if (input.grade === "subclinical") {
    return buildResult({
      primaryRecommendation: "no_treatment_subclinical",
      recommendationLabel: "Observation — No Treatment Indicated",
      rationale:
        "AUA/ASRM (Strong, Grade C) and EAU 2024 guidelines do not recommend treatment for subclinical varicoceles detected only on ultrasound. There is no solid evidence that repair improves semen parameters or pregnancy rates in subclinical disease.",
      embolizationCandidate: false,
      embolizationNotes: ["Not indicated for subclinical varicocele."],
      surgeryCandidate: false,
      surgeryNotes: ["Not indicated for subclinical varicocele."],
      treatmentIndicated: false,
      indicationReason: "Subclinical varicocele — no clinical indication for repair.",
      warnings: [
        "Routine scrotal ultrasound to identify non-palpable varicoceles is not recommended by AUA/ASRM or EAU.",
      ],
      urgentFlags,
      fertilityContext:
        "If infertility is the concern, evaluation should focus on other correctable causes. Subclinical varicocele repair has not demonstrated benefit.",
      nextSteps: [
        "Semen analysis if infertility is a concern",
        "Reassess if varicocele becomes clinically palpable",
        "Urology/andrology referral if infertility persists",
      ],
      evidenceLevel: "C",
      guidelineSource: "AUA/ASRM 2022 (Strong Rec, Grade C); EAU 2024",
      embolizationTechNotes: [],
    });
  }

  // ── Step 3: Determine treatment indication ──
  let treatmentIndicated = false;
  let indicationReason = "";

  const hasPainIndication =
    input.pain === "persistent_moderate" || input.pain === "severe_limiting";
  const hasFertilityIndication =
    input.infertilityDuration > 0 &&
    input.semenQuality !== "normal" &&
    !input.nonObstructiveAzoospermia;
  const hasAtrophyIndication =
    input.isAdolescent && input.testicularAtrophy && input.atrophyPercent >= 20;
  const hasSdfIndication =
    input.sdfElevated && input.priorArtFailure && input.infertilityDuration > 0;

  if (hasPainIndication) {
    treatmentIndicated = true;
    indicationReason = "Persistent scrotal pain refractory to conservative measures";
    nextSteps.push("Varicocele repair for pain: ~80% response rate (SIR/CIRSE 2023)");
  }
  if (hasFertilityIndication) {
    treatmentIndicated = true;
    indicationReason = indicationReason
      ? indicationReason + "; infertility with abnormal semen parameters"
      : "Infertility with palpable varicocele and abnormal semen parameters";
  }
  if (hasAtrophyIndication) {
    treatmentIndicated = true;
    indicationReason = indicationReason
      ? indicationReason + `; testicular atrophy (${input.atrophyPercent}% discrepancy)`
      : `Adolescent testicular atrophy (${input.atrophyPercent}% volume discrepancy > 20% threshold)`;
    warnings.push(
      "Adolescent varicocele: monitor for 6–12 months for spontaneous catch-up growth before intervention unless atrophy is progressive."
    );
  }
  if (hasSdfIndication) {
    treatmentIndicated = true;
    indicationReason = indicationReason
      ? indicationReason + "; elevated SDF with ART failure"
      : "Elevated sperm DNA fragmentation with prior ART failure";
    warnings.push(
      "EAU 2024 (Weak Recommendation): varicocelectomy may be considered for elevated SDF with unexplained infertility or failed ART. Evidence for improved live birth rates remains limited."
    );
  }

  // ── Step 4: NOA pathway ──
  if (input.nonObstructiveAzoospermia) {
    warnings.push(
      "Non-obstructive azoospermia (NOA): AUA/ASRM states there is no definitive evidence supporting varicocele repair prior to ART. Varicocele repair may increase sperm retrieval rate at micro-TESE (OR 2.65; PMID 40034026) but should be individualized."
    );
    return buildResult({
      primaryRecommendation: "multidisciplinary_noa",
      recommendationLabel: "Multidisciplinary Evaluation — NOA",
      rationale:
        "AUA/ASRM Expert Opinion: inform couples with clinical varicocele and NOA of the absence of definitive evidence supporting varicocele repair prior to ART. A recent meta-analysis (PMID 40034026) showed higher sperm retrieval rates at micro-TESE after varicocele repair (OR 2.65), but this has not translated to confirmed live birth rate improvements.",
      embolizationCandidate: false,
      embolizationNotes: [
        "Embolization is not first-line for NOA; microsurgical varicocelectomy is preferred if repair is pursued.",
      ],
      surgeryCandidate: true,
      surgeryNotes: [
        "Microscopic subinguinal varicocelectomy if repair is pursued before micro-TESE.",
      ],
      treatmentIndicated: false,
      indicationReason: "NOA — individualized decision with reproductive endocrinology and urology",
      warnings,
      urgentFlags,
      fertilityContext:
        "Discuss micro-TESE with IVF/ICSI as primary pathway. Varicocele repair may be considered to improve micro-TESE sperm retrieval rates but should not delay ART in couples with advanced female partner age.",
      nextSteps: [
        "Reproductive endocrinology/urology multidisciplinary consultation",
        "Karyotype and Y-chromosome microdeletion testing",
        "Hormone panel: FSH, LH, testosterone, inhibin B",
        "Discuss micro-TESE + IVF/ICSI as primary pathway",
      ],
      evidenceLevel: "Expert",
      guidelineSource: "AUA/ASRM 2022 (Expert Opinion); PMID 40034026",
      embolizationTechNotes: [],
    });
  }

  // ── Step 5: Partner age / ART timing consideration ──
  if (input.partnerAge >= 37 && input.infertilityDuration > 0) {
    warnings.push(
      "Female partner age ≥37: consider simultaneous varicocele repair + ART rather than sequential approach to avoid delaying ART. Semen improvement takes 3–6 months post-repair."
    );
  }

  // ── Step 6: No treatment indication ──
  if (!treatmentIndicated) {
    return buildResult({
      primaryRecommendation: "observe_monitor",
      recommendationLabel: "Observation and Monitoring",
      rationale:
        "Current clinical picture does not meet AUA/ASRM or EAU treatment thresholds. Treatment is indicated for: (1) persistent pain refractory to conservative measures, (2) infertility with palpable varicocele and abnormal semen parameters, or (3) adolescent testicular atrophy >20%.",
      embolizationCandidate: false,
      embolizationNotes: [],
      surgeryCandidate: false,
      surgeryNotes: [],
      treatmentIndicated: false,
      indicationReason: "No current treatment indication met",
      warnings,
      urgentFlags,
      fertilityContext:
        input.infertilityDuration > 0
          ? "Infertility evaluation ongoing — if semen parameters worsen or remain abnormal at follow-up, reassess treatment indication."
          : "No active fertility concern. Annual follow-up with semen analysis if planning future conception.",
      nextSteps: [
        "Semen analysis in 6–12 months if fertility is a future concern",
        "Reassess pain management with NSAIDs and scrotal support",
        "Urology follow-up if symptoms progress",
      ],
      evidenceLevel: "B",
      guidelineSource: "AUA/ASRM 2022; EAU 2024",
      embolizationTechNotes: [],
    });
  }

  // ── Step 7: Recurrent varicocele after prior surgery → embolization preferred ──
  if (input.priorTreatment === "prior_surgery_recurrent") {
    embolizationNotes.push(
      "Percutaneous embolization is the preferred approach for recurrent varicocele after surgical repair (AUA/ASRM; CIRSE 2023). Avoids re-operative field and associated adhesion risk."
    );
    embolizationNotes.push(
      "Technical success rate: 85–95% for experienced operators (SIR QI Guidelines 2021)."
    );
    embolizationTechNotes.push(
      "Retrograde approach via right femoral or right internal jugular vein; coil ± sclerosant (sodium tetradecyl sulfate or polidocanol foam) embolization of internal spermatic vein."
    );
    embolizationTechNotes.push(
      "Failure to access the spermatic vein occurs in 8–30% of cases; have surgical backup plan."
    );
    nextSteps.push("IR consultation for percutaneous varicocele embolization");
    nextSteps.push("Pre-procedure Doppler ultrasound to map venous anatomy");
    nextSteps.push("Post-procedure semen analysis at 3 and 6 months");

    return buildResult({
      primaryRecommendation: "embolization_for_recurrence",
      recommendationLabel: "Percutaneous Embolization — Preferred for Recurrence",
      rationale:
        "AUA/ASRM and CIRSE 2023 guidelines recommend percutaneous embolization as the preferred treatment for recurrent varicocele after surgical repair. It avoids the re-operative field, has a lower hydrocele risk than repeat surgery, and achieves comparable semen parameter improvement.",
      embolizationCandidate: true,
      embolizationNotes,
      surgeryCandidate: true,
      surgeryNotes: [
        "Inguinal microsurgical varicocelectomy is an alternative if embolization access fails.",
        "Avoid subinguinal approach if prior subinguinal surgery was performed.",
      ],
      treatmentIndicated: true,
      indicationReason,
      warnings,
      urgentFlags,
      fertilityContext: buildFertilityContext(input),
      nextSteps,
      evidenceLevel: "B",
      guidelineSource: "AUA/ASRM 2022; CIRSE Standards of Practice 2023; SIR QI Guidelines 2021",
      embolizationTechNotes,
    });
  }

  // ── Step 8: Primary treatment — embolization vs surgery ──
  // Determine embolization candidacy
  const embolizationFavored =
    input.preferMinimallyInvasive ||
    input.generalAnesthesiaRisk;

  const surgeryFavored =
    !input.preferMinimallyInvasive &&
    !input.generalAnesthesiaRisk;

  // Build embolization notes
  embolizationNotes.push(
    "Percutaneous embolization: minimally invasive, outpatient, local anesthesia/IV sedation, no incision."
  );
  embolizationNotes.push(
    "Technical success: 85–95%; recurrence rate 10–15% (higher than microsurgery). Chen et al. 2025 meta-analysis: lower overall complication rate vs surgical ligation (OR 0.65; PMID 41137990)."
  );
  embolizationNotes.push(
    "Hydrocele risk: <1% (significantly lower than surgical repair at 3–10%)."
  );
  if (input.anatomicAccessConcern) {
    warnings.push(
      "Anatomic access concern noted: catheter navigation to the internal spermatic vein may be technically challenging. Failure to access occurs in 8–30% of cases (PMID 26658060)."
    );
  }

  // Build surgery notes
  surgeryNotes.push(
    "Microscopic subinguinal or inguinal varicocelectomy: AUA/ASRM and EAU gold standard. Highest success rate, lowest recurrence (2–5%), lowest hydrocele risk among surgical approaches."
  );
  surgeryNotes.push(
    "Semen parameter improvement: 60–80%; spontaneous pregnancy rate improvement: 26–37% (PMID 40034026)."
  );
  surgeryNotes.push(
    "Laparoscopic approach: acceptable alternative but higher recurrence and hydrocele rates than microsurgery."
  );

  // Technical notes for embolization
  embolizationTechNotes.push(
    "Access: right common femoral vein or right internal jugular vein approach."
  );
  embolizationTechNotes.push(
    "Target: left internal spermatic vein (gonadal vein) — enters left renal vein at ~90°. Right gonadal vein enters IVC directly."
  );
  embolizationTechNotes.push(
    "Embolic agents: coils (0.035\" or 0.018\" micro-coils) ± liquid sclerosant (sodium tetradecyl sulfate 3%, polidocanol foam). Coil-only or combination approach per operator preference."
  );
  embolizationTechNotes.push(
    "Embolize from distal to proximal to prevent collateral recanalization. Treat all collateral channels identified on venography."
  );
  embolizationTechNotes.push(
    "Post-procedure: same-day discharge, scrotal support, avoid strenuous activity × 48 hours."
  );
  if ((input.laterality as string) === "bilateral") {
    embolizationTechNotes.push(
      "Bilateral varicocele: both gonadal veins can be treated in a single session via the same venous access."
    );
  }

  // Next steps
  nextSteps.push("Urology/andrology consultation to confirm treatment indication");
  nextSteps.push("Scrotal Doppler ultrasound to map venous anatomy pre-procedure");
  if (embolizationFavored) {
    nextSteps.push("IR consultation for percutaneous varicocele embolization");
  } else {
    nextSteps.push("Urology referral for microscopic varicocelectomy");
  }
  if (input.infertilityDuration > 0) {
    nextSteps.push("Semen analysis at 3 and 6 months post-treatment");
    nextSteps.push("Female partner fertility evaluation (ovarian reserve, tubal patency)");
  }
  if (input.pain !== "none") {
    nextSteps.push("NSAIDs and scrotal support as bridge to definitive repair");
  }

  // Determine primary recommendation
  let primaryRecommendation: TreatmentRecommendation;
  let recommendationLabel: string;
  let rationale: string;
  let evidenceLevel: EvidenceLevel;

  if (embolizationFavored && !surgeryFavored) {
    primaryRecommendation = "embolization_preferred";
    recommendationLabel = "Percutaneous Embolization — Preferred";
    rationale =
      "Patient profile favors percutaneous embolization: minimally invasive preference, high surgical risk, or recurrent disease. CIRSE 2023 and SIR guidelines support embolization as an effective, guideline-endorsed alternative to surgery with lower complication rates (Chen et al. 2025, OR 0.65 for complications vs surgical ligation; PMID 41137990). Recurrence rate is higher than microsurgery (10–15% vs 2–5%) but acceptable given lower procedural risk.";
    evidenceLevel = "B";
  } else if (surgeryFavored && !embolizationFavored) {
    primaryRecommendation = "surgery_preferred";
    recommendationLabel = "Microscopic Varicocelectomy — Preferred";
    rationale =
      "AUA/ASRM (Moderate Recommendation, Grade B) and EAU 2024 guidelines recommend microscopic varicocelectomy as the gold standard for primary treatment. It achieves the highest success rate, lowest recurrence (2–5%), and lowest hydrocele rate among surgical approaches. Semen parameter improvement in 60–80% of patients; spontaneous pregnancy rate improvement 26–37%.";
    evidenceLevel = "B";
  } else {
    primaryRecommendation = "embolization_or_surgery";
    recommendationLabel = "Embolization or Microsurgery — Shared Decision";
    rationale =
      "Both percutaneous embolization and microscopic varicocelectomy are guideline-endorsed options. Surgery (microscopic varicocelectomy) has the highest success and lowest recurrence rate per AUA/ASRM and EAU 2024. Embolization offers a minimally invasive alternative with lower complication rates (PMID 41137990) but higher recurrence (10–15%). Decision should be individualized based on patient preference, anatomy, and operator expertise.";
    evidenceLevel = "B";
  }

  return buildResult({
    primaryRecommendation,
    recommendationLabel,
    rationale,
    embolizationCandidate: true,
    embolizationNotes,
    surgeryCandidate: true,
    surgeryNotes,
    treatmentIndicated: true,
    indicationReason,
    warnings,
    urgentFlags,
    fertilityContext: buildFertilityContext(input),
    nextSteps,
    evidenceLevel,
    guidelineSource:
      "AUA/ASRM 2022 (Moderate Rec, Grade B); EAU Male Infertility 2024; CIRSE Standards of Practice 2023; SIR QI Guidelines 2021 (PMID 33610449); Chen et al. 2025 (PMID 41137990)",
    embolizationTechNotes,
  });
}

// ─── Helper Functions ────────────────────────────────────────────────────────

function buildFertilityContext(input: VaricoceleInput): string {
  if (input.infertilityDuration === 0) {
    if (input.pain !== "none") {
      return "Pain is the primary indication. No active fertility concern reported.";
    }
    return "No active fertility concern. Treatment indicated for symptom relief or atrophy prevention.";
  }

  const parts: string[] = [];
  parts.push(`Infertility duration: ${input.infertilityDuration} months.`);
  if (input.partnerAge > 0) {
    parts.push(`Female partner age: ${input.partnerAge} years.`);
  }
  if (input.partnerFertilityStatus !== "not_applicable") {
    const statusMap: Record<string, string> = {
      normal: "Female partner fertility: normal.",
      reduced: "Female partner fertility: reduced — ART may be needed regardless of varicocele repair.",
      unknown: "Female partner fertility: not yet evaluated — complete female workup recommended.",
    };
    parts.push(statusMap[input.partnerFertilityStatus] ?? "");
  }
  if (input.sdfElevated) {
    parts.push("Elevated SDF: varicocele repair may reduce SDF by 6–7% (EAU 2024 Weak Recommendation).");
  }
  if (input.priorArtFailure) {
    parts.push("Prior ART failure: varicocele repair before repeat ART may improve outcomes.");
  }
  return parts.join(" ");
}

function buildResult(params: VaricoceleRecommendation): VaricoceleRecommendation {
  return params;
}

// ─── Display Helpers ─────────────────────────────────────────────────────────

export function getRecommendationColor(rec: TreatmentRecommendation): string {
  switch (rec) {
    case "embolization_preferred":
    case "embolization_for_recurrence":
      return "blue";
    case "surgery_preferred":
      return "green";
    case "embolization_or_surgery":
      return "teal";
    case "observe_monitor":
      return "yellow";
    case "no_treatment_subclinical":
      return "gray";
    case "art_without_repair":
      return "purple";
    case "multidisciplinary_noa":
      return "orange";
    default:
      return "gray";
  }
}

export function getGradeLabel(grade: VaricoceleGrade): string {
  switch (grade) {
    case "subclinical":
      return "Subclinical (Ultrasound-Only)";
    case "grade1":
      return "Grade I (Palpable with Valsalva only)";
    case "grade2":
      return "Grade II (Palpable without Valsalva)";
    case "grade3":
      return "Grade III (Visible — 'Bag of Worms')";
  }
}

export function getSemenQualityLabel(q: SemenQuality): string {
  switch (q) {
    case "normal":
      return "Normal (WHO 6th ed. 2021)";
    case "mildly_abnormal":
      return "Mildly Abnormal (1 parameter below reference)";
    case "moderately_abnormal":
      return "Moderately Abnormal (2+ parameters below reference)";
    case "severely_abnormal":
      return "Severely Abnormal (severe oligo/astheno/teratospermia)";
    case "azoospermia":
      return "Azoospermia";
  }
}
